    "property_id": "PROP-56ad1eb2-inv-005",
    "text": "Fork digest must incorporate blob parameters; mismatched digests cause network partition.",
    "type": "invariant",
    "assertion": "forall epoch e: fork_digest(e) == trunc4(fork_data_root(e) XOR hash(blob_params(e)))",
